with
-- node: Proj_Header (ProjectionView)
proj_header as (
    select
        sd_vbak.VBELN as VBELN,
        sd_vbak.VKORG as VKORG,
        sd_vbak.ERDAT as ERDAT,
        datediff(day, to_date("ERDAT"), current_timestamp()) as DAYS_OPEN
    from sd_vbak as sd_vbak
    where "VKORG" = '1000' and "ERDAT" >= {{ var('ip_from_date', '2024-01-01') }}
),

-- node: Proj_Item (ProjectionView)
proj_item as (
    select
        sd_vbap.VBELN as VBELN,
        sd_vbap.MATNR as MATNR,
        "KWMENG" * "NETPR" as LINE_AMOUNT
    from sd_vbap as sd_vbap
),

-- node: Join_Main (JoinView)
join_main as (
    select
        proj_header.VBELN as VBELN,
        proj_header.VKORG as VKORG,
        proj_item.MATNR as MATNR,
        proj_item.LINE_AMOUNT as LINE_AMOUNT
    from proj_header as proj_header
    left outer join proj_item as proj_item
      on proj_header.VBELN = proj_item.VBELN
),

-- node: Agg_Sales (AggregationView)
agg_sales as (
    select
        join_main.VKORG as VKORG,
        join_main.MATNR as MATNR,
        sum(join_main.LINE_AMOUNT) as GROSS
    from join_main as join_main
    group by VKORG, MATNR
),

-- node: Proj_Legacy (ProjectionView)
proj_legacy as (
    select
        sd_legacy.VKORG as VKORG,
        sd_legacy.MATNR as MATNR,
        sd_legacy.AMOUNT as GROSS,
        'LEGACY' as SOURCE_KBN
    from sd_legacy as sd_legacy
),

-- node: Union_All (UnionView)
union_all as (
    select
        VKORG as VKORG,
        MATNR as MATNR,
        GROSS as GROSS,
        'BW' as SOURCE_KBN
    from agg_sales
    union all
    select
        VKORG as VKORG,
        MATNR as MATNR,
        GROSS as GROSS,
        SOURCE_KBN as SOURCE_KBN
    from proj_legacy
),

-- node: Rank_Top (RankView)
rank_top as (
    select
        VKORG,
        MATNR,
        GROSS,
        SOURCE_KBN
    from (
    select
        union_all.VKORG as VKORG,
        union_all.MATNR as MATNR,
        union_all.GROSS as GROSS,
        union_all.SOURCE_KBN as SOURCE_KBN,
        row_number() over (partition by VKORG order by GROSS desc) as __rn
    from union_all as union_all
    ) as ranked
    where __rn <= 10
)

select
    VKORG,
    MATNR,
    SOURCE_KBN,
    "GROSS" / 10 as GROSS_PER_ITEM,
    GROSS
from rank_top
